// File paths, import specifiers and the generated-file header shared by every emitter. The header doubles as the
// ownership mark src/write.ts uses to tell generated files from hand-written ones.
// VERIFIED: test/write.test.ts shows a second run into the same directory recognizes files by this header.
import { posix } from "node:path";

/** Generated output: path relative to the output directory → file content. The one Stage 2 output type. */
export type Files = Map<string, string>;

export const HEADER = "/**\n * This file was generated by open-api-gen. Do not edit.\n */\n";

/**
 * The `import` specifier from one generated file to another.
 * It ends in `.js` so it resolves under the bundler, node16 and nodenext module resolution modes alike.
 */
export function importPath(fromFile: string, toFile: string): string {
  const relativePath = posix.relative(posix.dirname(fromFile), toFile).replace(/\.ts$/, ".js");
  if (relativePath.startsWith(".")) {
    return relativePath;
  }
  return `./${relativePath}`;
}

/**
 * Hook modules named in the config are either package names or paths relative to the output directory.
 * A relative path is rewritten so it still points at the same module from a file nested inside the output.
 */
export function hookImportPath(fromFile: string, moduleSpecifier: string): string {
  const isRelative = moduleSpecifier.startsWith("./") || moduleSpecifier.startsWith("../");
  if (!isRelative) {
    return moduleSpecifier;
  }
  return importPath(fromFile, posix.normalize(moduleSpecifier));
}
